class Temperature:
    def __init__(self, celsius: float) -> None:
        self.celsius = float(celsius)          # single validated entry point

    @classmethod
    def from_fahrenheit(cls, f: float) -> "Temperature":
        return cls((f - 32) * 5 / 9)           # goes through __init__ and cls

